"""Build source-pose review for independently selectable Base shell candidates."""
import argparse,json
from pathlib import Path


def main():
    ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('out',type=Path);a=ap.parse_args();out=a.out.resolve();views={}
    for name,pattern in [('Base · front oblique','whole-{}-e15-a60'),('Base · rear','whole-{}-e15-a180'),('Base · top','whole-{}-top'),('Base · underside','whole-{}-bottom'),('Crossbar · oblique','member-4268930-{}-oblique'),('Crossbar · underside','member-4268930-{}-bottom'),('Crossbar · rear','member-4268930-{}-back'),('Tall cover · oblique','member-4392221-{}-oblique'),('Lower housing · oblique','member-4527988-{}-oblique'),('Backing · oblique','member-4664029-{}-oblique'),('Backing · reverse','member-4664029-{}-reverse'),('Upper backing · reverse','member-4756187-{}-reverse')]:views[name]={stage:str(out/(pattern.format(stage)+'.png')) for stage in ['before','skins','shells']}
    html='''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{margin:0;color:var(--foreground);font-family:var(--font-sans),sans-serif}h2{font-size:22px;margin:0 0 14px}.stats{display:flex;gap:24px;flex-wrap:wrap}.stats strong{display:block;font-size:24px}.stats span,p{font-size:13px;color:var(--muted-foreground)}nav{display:flex;gap:7px;flex-wrap:wrap;margin:14px 0}select,button{font:inherit;font-size:13px;padding:8px 10px;border:1px solid var(--border);border-radius:6px;color:var(--foreground);background:var(--card)}button.active{color:var(--primary-foreground);background:var(--primary)}.pair{display:grid;grid-template-columns:1fr 1fr;gap:10px}.pair img{width:100%;border-radius:6px}.label{font-size:12px;margin-bottom:6px}p{line-height:1.55}.note{background:var(--muted);padding:16px;border-radius:8px;margin-top:12px}.note p{margin:0}.footer{margin-bottom:0}</style></head><body><h2>Base shells: two independently reviewable steps</h2><div class="stats"><div><strong id="tri">68,080</strong><span id="saving">17.4% fewer visual triangles</span></div><div><strong>10,494</strong><span>crossbar · previously 18,456</span></div><div><strong>162</strong><span>four backing plates · previously 5,348</span></div></div><nav><button id="shells" class="active">Skins + backing plates</button><button id="skins">Keep original backings</button><select id="view" aria-label="Comparison view"></select></nav><div class="pair"><div><div class="label">Approved · 82,414 triangles</div><img id="before" alt="Approved Base"></div><div><div class="label" id="candidate-label">Candidate · 68,080 triangles</div><img id="candidate" alt="Candidate Base"></div></div><div class="note"><p id="policy"><b>Backing approximation:</b> source-outline 1.5 mm plates replace molded ribs/posts. Up to 13.21 mm local difference; use the isolated backing views to inspect this deliberately larger change.</p></div><p>All 2,822 light triangles keep exact positions, normals and materials. Source member identities and collision stay unchanged. The crossbar uses a 3 mm sampled detail guard; planar patches preserve apertures and retain compact boundary loops.</p><p class="footer">18 assembled views: at most 0.076% silhouette-mask difference. Green LED masks are unchanged; the underside’s three red pixels disappear with plates. Fixed source-pose diagnostic renders, not runtime PBR or every moving pose. Neither candidate is installed.</p><script>const views=DATA;let stage='shells';const view=document.getElementById('view');for(const k of Object.keys(views))view.add(new Option(k,k));function update(){document.getElementById('before').src=views[view.value].before;document.getElementById('candidate').src=views[view.value][stage];const plated=stage==='shells';document.getElementById('tri').textContent=plated?'68,080':'73,258';document.getElementById('saving').textContent=plated?'17.4% fewer visual triangles':'11.1% fewer visual triangles';document.getElementById('candidate-label').textContent=plated?'Candidate · 68,080 triangles':'Candidate · 73,258 triangles';document.getElementById('policy').innerHTML=plated?'<b>Backing approximation:</b> source-outline 1.5 mm plates replace molded ribs/posts. Up to 13.21 mm local difference; use the isolated backing views to inspect this deliberately larger change.':'<b>Backings retained:</b> this variant changes the crossbar and planar patches only. It retains the previous molded backing shells. The larger backing approximation is disabled.';for(const k of ['skins','shells'])document.getElementById(k).classList.toggle('active',k===stage);}view.onchange=update;for(const k of ['skins','shells'])document.getElementById(k).onclick=()=>{stage=k;update();};update();</script></body></html>'''.replace('DATA',json.dumps(views));(out/'review.html').write_text(html);print(out/'review.html')
if __name__=='__main__':main()
